mapper.codeEditorJavascript:
const MONTHS=['ינואר','פברואר','מרץ','אפריל','מאי','יוני','יולי','אוגוסט','ספטמבר','אוקטובר','נובמבר','דצמבר'];
const titles=(input.sheets||[]).map(s=>String((s.properties||{}).title||'').trim());
const nowIL=new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Jerusalem'}));
const tabs=[];
// RULE (15/11/2026): porting searches ONLY the current month tab of דוח מכר פלאפון (old tabs held duplicate rows without a customer number). Do not remove.
for(let k=0;k<=0;k++){const d=new Date(nowIL.getFullYear(),nowIL.getMonth()+k,1); const t=MONTHS[d.getMonth()]+' '+d.getFullYear(); if(titles.includes(t)) tabs.push(t);}
return {count:tabs.length, body: JSON.stringify({dataFilters: tabs.map(t=>({a1Range:"'"+t+"'!A1:AC3000"})), valueRenderOption:'FORMATTED_VALUE'})};

// inputs: text, repWa, repName, ranges, reps (valueRanges of 'יעדים' A:B)
// RULE (Steve 12/11/2026): the rep writes only ניוד + customer name OR a phone + when. Customer number, main phone and ID are taken from the דוח מכר פלאפון. A phone the rep writes that is not the main one (son, wife...) is the call-back number in the email. Not found in the report -> do not send, tell the rep. Do not remove.
const wa9 = v => String(v || '').replace(/\D/g, '').replace(/^972/, '').replace(/^0/, '');
let repRows = input.reps || [];
if (repRows.length && repRows[0] && repRows[0].valueRange) repRows = repRows[0].valueRange.values || [];
const repSet = new Set(['544604246']);
for (const r of repRows) { const p = wa9(r && r[1]); if (/^5\d{8}$/.test(p)) repSet.add(p); }
if (!repSet.has(wa9(input.repWa))) return {action: 'notrep', reply: '⛔ המספר שלך לא רשום כנציג (לשונית יעדים), אז לא שלחתי בקשת ניוד. פנה/י לירדן.', key: '', phone: ''};
const TZ = 'Asia/Jerusalem';
const fmt = new Intl.DateTimeFormat('en-US', {timeZone: TZ, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', weekday: 'short'});
function ilParts(t) { const o = {}; for (const p of fmt.formatToParts(new Date(t))) o[p.type] = p.value; return {y: +o.year, m: +o.month - 1, d: +o.day, h: +o.hour % 24, mi: +o.minute, wd: ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].indexOf(o.weekday)}; }
function ilToUtc(y, m, d, h, mi) { const want = Date.UTC(y, m, d, h, mi); let t = want; for (let i = 0; i < 3; i++) { const p = ilParts(t); t += want - Date.UTC(p.y, p.m, p.d, p.h, p.mi); } return t; }
const pad = n => String(n).padStart(2, '0');
const norm = s => String(s || '').replace(/[\s‏‎]+/g, ' ').trim();
const digits = s => String(s || '').replace(/\D/g, '');
const DAYS = ['ראשון', 'שני', 'שלישי', 'רביעי', 'חמישי', 'שישי', 'שבת'];
const now = input.nowMs ? +input.nowMs : Date.now();
const np = ilParts(now);

function plan(text) {
  let c = ' ' + text.replace(/[״"׳']/g, '') + ' ';
  let dayOffset = null, explicitDay = false, h = null, mi = 0, target = null;
  const dm = c.match(/(\d{1,2})\s*[./]\s*(\d{1,2})(?:\s*[./]\s*\d{2,4})?/);
  if (dm) {
    const d = +dm[1], m = +dm[2] - 1;
    if (d >= 1 && d <= 31 && m >= 0 && m <= 11) {
      let y = np.y; if (Date.UTC(y, m, d) < Date.UTC(np.y, np.m, np.d) - 60 * 864e5) y++;
      target = {y, m, d}; explicitDay = true;
    }
    c = c.replace(dm[0], ' ');
  }
  if (!target) {
    if (/מחרתיים/.test(c)) { dayOffset = 2; explicitDay = true; }
    else if (/מחר/.test(c)) { dayOffset = 1; explicitDay = true; }
    else if (/היום|הערב(?!\S)/.test(c)) { dayOffset = 0; explicitDay = true; }
    else {
      for (let i = 0; i < 7; i++) {
        if (new RegExp('יום\\s*' + DAYS[i] + '(?!\\S)').test(c) || new RegExp('\\s' + DAYS[i] + '\\s').test(c)) {
          dayOffset = (i - np.wd + 7) % 7; explicitDay = true; break;
        }
      }
    }
  }
  const hm = c.match(/(\d{1,2})\s*:\s*(\d{2})/);
  const evening = /ערב/.test(c), morningWord = /בוקר/.test(c), noonWord = /אחה|אחר הצהריים|צהריים|צהרים/.test(c);
  if (hm) { h = +hm[1]; mi = +hm[2]; }
  else { const bare = c.match(/(?:^|[^\d])(\d{1,2})(?![\d:./])/); if (bare) { h = +bare[1]; mi = 0; } }
  if (h !== null) {
    if (evening && h < 12) h += 12;
    else if (!morningWord && h >= 1 && h <= 7) h += 12;
    if (h > 23 || mi > 59) return null;
  } else if (/עכשיו|מיידי|מייד|מיד|כעת|דחוף/.test(c)) h = 'now';
  else if (morningWord) { h = 10; mi = 0; }
  else if (noonWord) { h = 17; mi = 30; }
  else return null;
  let base;
  if (target) base = target;
  else { const t = new Date(Date.UTC(np.y, np.m, np.d + (dayOffset || 0))); base = {y: t.getUTCFullYear(), m: t.getUTCMonth(), d: t.getUTCDate()}; }
  let when = h === 'now' ? now : ilToUtc(base.y, base.m, base.d, h, mi);
  if (when < now - 5 * 60e3) {
    if (explicitDay) return {past: true};
    when = ilToUtc(base.y, base.m, base.d + 1, h, mi);
  }
  let wp = ilParts(when);
  if (wp.wd === 6) { const hh = h === 'now' ? 10 : h, mm = h === 'now' ? 0 : mi; when = ilToUtc(wp.y, wp.m, wp.d + 1, hh, mm); }
  if (when < now) when = now;
  wp = ilParts(when);
  const diff = Math.round((Date.UTC(wp.y, wp.m, wp.d) - Date.UTC(np.y, np.m, np.d)) / 864e5);
  const isNow = when - now < 6 * 60e3;
  const dayTxt = diff === 0 ? 'היום' : diff === 1 ? 'מחר' : 'ביום ' + DAYS[wp.wd] + ' ' + pad(wp.d) + '/' + pad(wp.m + 1);
  return {iso: new Date(when).toISOString(), text: isNow ? 'עכשיו (תוך כמה דקות)' : dayTxt + ' ב-' + pad(wp.h) + ':' + pad(wp.mi)};
}

const raw = String(input.text || '').replace(/[‎‏‪-‮⁦-⁩]/g, '').replace(/[‐-―−­]/g, '-').replace(/ /g, ' ');
const force = /(^|[^֐-׿])שוב(?![֐-׿])/.test(raw);
let t = ' ' + raw.replace(/^\s*ניוד(ים)?\s*[:\-–]?/, ' ').replace(/(^|[^֐-׿])שוב(?![֐-׿])/g, '$1 ').replace(/בבקשה|תודה|לנייד|ניוד/g, ' ') + ' ';
let phone = '', idNum = '', custNum = '', m;
m = t.match(/(?:ת\.?\s*ז\.?|ת["'״׳]ז|תעודת\s*זהות)\s*[:\-]?\s*(\d{7,9})/); if (m) { idNum = m[1]; t = t.replace(m[0], ' '); }
m = t.match(/(?:מס(?:פר)?['׳.]?\s*לקוח|לקוח|מ["'״׳]ל)\s*[:\-]?\s*(\d{5,9})/); if (m) { custNum = m[1]; t = t.replace(m[0], ' '); }
m = t.match(/(?:\+?972[-\s]?|0)(5\d)[-\s]?(\d{3})[-\s]?(\d{4})(?!\d)/); if (m) { phone = '0' + m[1] + m[2] + m[3]; t = t.replace(m[0], ' '); }
const loose = [];
t = t.replace(/(?<![\d/.:])\d{5,10}(?![\d/.:])/g, x => { loose.push(x); return ' '; });

const rows = [];
for (const vr of (input.ranges || [])) {
  const tab = String((vr.valueRange || {}).range || '').split('!')[0].replace(/^'|'$/g, '');
  const vals = (vr.valueRange && vr.valueRange.values) || [];
  for (let i = 1; i < vals.length; i++) {
    const r = vals[i];
    rows.push({tab, row: i + 1, name: norm(r[2]), phone: digits(r[3]).replace(/^972/, '').replace(/^0/, ''), id: digits(r[4]).replace(/^0+/, ''), cust: digits(r[9]), qty: parseInt(r[14], 10) || 0, rep: norm(r[0]), lines: r.slice(15, 25).map(x => digits(x).replace(/^972/, '').replace(/^0/, '')).filter(Boolean)});
  }
}
const n0 = s => digits(s).replace(/^0+/, '');
for (const x of loose) {
  const v = n0(x);
  if (!custNum && rows.some(r => r.cust && r.cust === v)) { custNum = v; continue; }
  if (!idNum && rows.some(r => r.id && r.id === v)) { idNum = v; continue; }
  if (!phone && /^0?5\d{8}$/.test(x)) { phone = '0' + x.replace(/^0/, ''); continue; }
  if (!idNum && x.length >= 9) { idNum = x; continue; }
  if (!custNum) { custNum = v; continue; }
  if (!idNum) idNum = x;
}
const local9 = phone ? phone.slice(1) : '';
let hit = null;
// RULE (Steve, 05/11/2026): the phone written in the rep's message is the one that goes in the email (not the customer's main number). A phone of ANY of the customer's lines (main or מספר 1-10) finds the customer.
const byPhone = local9 ? rows.filter(r => r.phone === local9 || r.lines.includes(local9)) : [];
const byCust = custNum ? rows.filter(r => r.cust === n0(custNum)) : [];
const byId = idNum ? rows.filter(r => r.id === n0(idNum)) : [];
// RULE (15/11/2026, כפילויות): אותו לקוח בשתי שורות בדוח - לוקחים את השורה עם מספר לקוח (אח"כ עם ת"ז, אח"כ המאוחרת). אם יש שני מספרי לקוח שונים - כמו קודם (השורה הראשונה). Do not remove.
const PICK = a => { if (!a.length) return null; if (new Set(a.map(r => r.cust).filter(Boolean)).size > 1) return a[0]; const sc = r => (r.cust ? 2 : 0) + (r.id ? 1 : 0); let b = a[0]; for (const r of a) if (sc(r) >= sc(b)) b = r; return b; };
hit = PICK(byCust.length ? byCust : byPhone.length ? byPhone : byId);
if (byCust.length > 1 && local9) hit = PICK(byCust.filter(r => r.phone === local9 || r.lines.includes(local9))) || hit;
const PREF = w => w.replace(/^[לבהו](?=[֐-׿]{2,})/, '');
const tw = /^(ב?שעה|בשעות|שעות|היום|מחר|מחרתיים|הערב|ערב|בערב|בוקר|בבוקר|אחה|אחהצ|צהריים|בצהריים|עכשיו|מיד|מיידי|דחוף|יום|ביום|ראשון|שני|שלישי|רביעי|חמישי|שישי|של|את|עם|הלקוח|לקוח|ללקוח|הלקוחה|לקוחה|טלפון|נייד|תז|מס|מספר|למספר|קווים|קו|כעת|אחר|הצהריים|אחרי|רוצה|רוצים|לחזור|חזרה|להתקשר|לחייג|של|הבן|הבת|האישה|הבעל|שלו|שלה|ב|ל)$/;
const nw0 = t.replace(/[^֐-׿\s]/g, ' ').split(/\s+/).filter(w => w && w.length > 1 && !tw.test(w));
let nameMulti = [];
if (!hit && nw0.length) {
  const match = ws => rows.filter(r => r.name && ws.every(w => r.name.includes(w)));
  let found = match(nw0);
  if (!found.length) found = match(nw0.map(PREF));
  // RULE (15/11/2026, כפילויות): חיפוש לפי שם - שתי שורות עם אותו טלפון (בלי שני מספרי לקוח שונים) הן לקוח אחד; שומרים את השורה עם מספר לקוח. Do not remove.
  const uniq = []; const seen = []; for (const r of found) { const k = r.cust || r.phone; const j = seen.findIndex(g => g.keys.has(k) || (r.phone && g.phones.has(r.phone) && !(r.cust && g.custs.size && !g.custs.has(r.cust)))); if (j < 0) { seen.push({keys: new Set([k]), phones: new Set([r.phone].filter(Boolean)), custs: new Set([r.cust].filter(Boolean))}); uniq.push(r); } else { const g = seen[j]; g.keys.add(k); if (r.phone) g.phones.add(r.phone); if (r.cust) g.custs.add(r.cust); if (!uniq[j].cust && r.cust) uniq[j] = r; } }
  if (uniq.length === 1) hit = uniq[0]; else if (uniq.length > 1) nameMulti = uniq;
}
if (hit) {
  if (!custNum) custNum = hit.cust;
  if (!phone && hit.phone) phone = '0' + hit.phone;
  if (!idNum && hit.id) idNum = hit.id;
}
const timeWords = /^(ב?שעה|בשעות|שעות|היום|מחר|מחרתיים|הערב|ערב|בערב|בוקר|בבוקר|אחה|אחהצ|אחה"צ|אחה״צ|צהריים|בצהריים|עכשיו|מיד|מיידי|דחוף|יום|ביום|ראשון|שני|שלישי|רביעי|חמישי|שישי|ב|ל|של|את|עם|הלקוח|לקוח|ללקוח|טלפון|נייד|תז|ת"ז|ת.ז|מס|מספר|קווים|קו|ב-|כעת|אחר|הצהריים|אחרי)$/;
const nameWords = t.replace(/[^֐-׿a-zA-Z\s"'״׳]/g, ' ').split(/\s+/).filter(w => w && w.length > 1 && !timeWords.test(w.replace(/["'״׳]/g, '')));
let name = hit && hit.name ? hit.name : nameWords.slice(0, 3).join(' ');

const sched = plan(t);

const errors = [];
if (!hit && !(phone && custNum)) {
  if (nameMulti.length) errors.push('מצאתי כמה לקוחות בשם הזה: ' + nameMulti.slice(0, 4).map(r => r.name + ' ' + ('0' + r.phone)).join(' | ') + ' - שלח/י שוב עם השם המלא או הטלפון הראשי במנוי');
  else errors.push('לא מצאתי את הלקוח בדוח מכר פלאפון' + (local9 ? ' לפי הטלפון ' + phone : '') + (nw0.length ? (local9 ? ' או' : '') + ' לפי השם ' + nw0.join(' ') : '') + ' - שלח/י את השם המלא או הטלפון הראשי במנוי. אם העסקה עוד לא בדוח, צריך להוסיף אותה קודם');
}
else if (!custNum) errors.push('ללקוח ' + name + ' אין מספר לקוח בדוח מכר פלאפון - צריך לעדכן אותו בדוח');
else if (!phone) errors.push('אין טלפון ללקוח בדוח - שלח/י את המספר שפלאפון יחזרו אליו');
if (!sched) errors.push('לא זיהיתי מתי לנייד (למשל: עכשיו / היום 14:00 / מחר בבוקר / אחה"צ)');
else if (sched.past) errors.push('השעה שביקשת כבר עברה');

const help = '❗ ' + errors.join('\n❗ ') + '\n\nכותבים: ניוד + שם הלקוח או הטלפון הראשי במנוי + מתי. למשל:\nניוד ישראל ישראלי היום 14:00\nניוד 0541234567 מחר בבוקר\nאם פלאפון צריכים לחזור למספר אחר (של הבן למשל), מוסיפים אותו:\nניוד ישראל ישראלי 0501234567 היום 14:00';
const ok = errors.length === 0;

let action, reply;
const qty = hit ? hit.qty : 0;
const otherPhone = hit && hit.phone && phone && phone.slice(1) !== hit.phone;
const who = '👤 ' + (name || 'לקוח') + ' (לקוח ' + custNum + ')\n📞 ' + phone + (otherPhone ? ' (פלאפון יחזרו למספר הזה, לא לראשי 0' + hit.phone + ')' : '') + (idNum ? '\n🪪 ת"ז ' + idNum : '') + (qty > 1 ? '\n📱 ' + qty + ' קווים' : '');
if (!ok) { action = 'error'; reply = help; }
else { action = 'schedule'; reply = '✅ קיבלתי! מייל לניודים יישלח ' + sched.text + '\n' + who + (hit ? '' : '\n\n⚠️ לא מצאתי את הלקוח בדוח מכר פלאפון - שולח לפי הפרטים ששלחת.') + '\n\nתקבל/י הודעה כשהמייל יישלח.'; }

const st = 'direction:rtl;font-family:Aptos,Aptos_EmbeddedFont,Aptos_MSFontService,Calibri,Helvetica,sans-serif;font-size:12pt;color:rgb(0,0,0)';
const lines = ['רוצה לנייד עכשיו בבקשה' + (qty > 1 ? ' ' + qty + ' קווים' : ''), 'לחייג ל-' + phone];
if (idNum) lines.push('ת"ז ' + idNum);
const html = lines.map(l => '<div style="' + st + '">' + l + '</div>').join('') +
  '<div style="' + st + '"><br /></div><div id="Signature"><p style="direction:rtl;margin-top:1em;margin-bottom:1em"><b>ירדן בן שלוש</b></p>' +
  '<p style="direction:rtl;margin-top:1em;margin-bottom:1em">מנכ”ל - יהל תקשורת</p>' +
  '<p style="direction:rtl;margin-top:1em;margin-bottom:1em">פתרונות תקשורת מתקדמים | משווק מורשה yes</p></div>';

let repWa = digits(input.repWa); if (repWa.startsWith('0')) repWa = '972' + repWa.slice(1);
return {
  action, reply, ok, who, force,
  key: phone ? '972' + phone.slice(1) : '', phone, custNum, subject: custNum, idNum, name, qty, html,
  sendAt: sched && !sched.past ? sched.iso : '', sendAtText: sched && !sched.past ? sched.text : '',
  choice: 'נציג: ' + norm(raw).slice(0, 200), repName: norm(input.repName), repWa,
  tab: hit ? hit.tab : '', row: hit ? hit.row : 0
};

// RULE (Steve, 20/10/2026): one porting email per customer per day (Israel time). Next day it can be sent again normally.
// Same-day extra email only if Pelephone answered 'ללא מענה' after the last email, or the rep explicitly writes 'ניוד שוב ...'.
const fmt = new Intl.DateTimeFormat('en-US', {timeZone: 'Asia/Jerusalem', hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit'});
const parts = t => { const o = {}; for (const p of fmt.formatToParts(new Date(t))) o[p.type] = p.value; return o; };
const dayKey = t => { const p = parts(t); return p.year + '-' + p.month + '-' + p.day; };
const st = String(input.prevStatus || ''), action0 = String(input.action || '');
const who = String(input.who || '');
const force = String(input.force) === 'true';
let action = action0, reply = String(input.reply || '');
if (action0 === 'schedule') {
  const prevMs = input.prevSentAt ? Date.parse(input.prevSentAt) : NaN;
  const naMs = input.naLast ? Date.parse(input.naLast) : NaN;
  const noAnswerSince = st === 'sent' && !isNaN(naMs) && (isNaN(prevMs) || naMs > prevMs);
  const sentToday = st === 'sent' && !isNaN(prevMs) && dayKey(prevMs) === dayKey(Date.now());
  if (st === 'sending') { action = 'block'; reply = '⛔ לא שלחתי - המייל לניודים על הלקוח הזה נשלח ממש עכשיו.\n' + who; }
  else if (sentToday && !noAnswerSince && !force) {
    const p = parts(prevMs);
    action = 'block';
    reply = '⛔ לא שלחתי - כבר נשלח היום מייל לניודים על הלקוח הזה (ב-' + p.hour + ':' + p.minute + ').\n' + who + '\n\nעל כל לקוח אפשר לשלוח מייל ניוד פעם ביום - מחר אפשר לשלוח שוב כרגיל.\n• אם פלאפון יחזירו "ללא מענה" - אפשר לשלוח שוב כבר היום.\n• אם הלקוח ביקש לתאם זמן אחר, כתוב/י "שוב" אחרי המילה ניוד, למשל:\nניוד שוב 0541234567 מחר 11:00';
  }
  else if (st === 'sent' && sentToday) { reply = (noAnswerSince ? '🔁 פלאפון החזירו "ללא מענה" - שולח מייל ניוד נוסף.\n' : '🔁 לבקשתך ("שוב") - שולח מייל ניוד נוסף.\n') + reply.replace(/^✅ קיבלתי! /, ''); }
  else if (st === 'pending') { reply = '🔄 עדכנתי! כבר היה מתוזמן מייל לניודים על הלקוח הזה (' + (input.prevText || '') + ') - עכשיו הוא יישלח ' + input.sendAtText + '\n' + who + '\n\nתקבל/י הודעה כשהמייל יישלח.'; }
}
return {action, reply};
